script:
ship_event = {
	id = origin.4997
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		from = {
			has_star_flag = broken_shackles_home_system_@root.owner
		}
		NOT = {
			owner = {
				has_country_flag = met_broken_shackles_homeworld
			}
		}
	}

	immediate = {
		from = {
			random_system_planet = {
				limit = {
					has_carrier_flag = broken_shackles_homeworld_@root.owner
				}
				save_event_target_as = bs_main_homeworld_planet
			}
		}
		if = {
			limit = {
				from = {
					exists = owner
					has_star_flag = broken_shackles_home_system_@root.owner
				}
			}
			ship_event = {
				id = origin.5000
				scopes = {
					from = event_target:bs_main_homeworld_planet
				}
			}
		}
	}
}

